SELECT

FROM asset ass

LEFT JOIN idc idc ON ass.idc_id = idc.id
LEFT JOIN cabinet cab ON ass.cabinet_id = cab.id
LEFT JOIN sys_user su ON ass.create_by = su.user_id
LEFT JOIN sys_user su1 ON ass.update_by = su1.user_id
LEFT JOIN asset_ping assp ON ass.host = assp.host
LEFT JOIN sys_area sa ON idc.area_id = sa.id




